def f(n):
    if n == 0:
        return 0
    m = 0
    temp = n
    while temp > 0 and temp % 2 == 0:
        temp //= 2
        m += 1
    return temp

solutions = []
for u in range(1, 101):
    diff = f(u + 1) - f(u)
    if diff % 4 == 0:
        solutions.append(u)

print("Solutions found for u <= 100:", solutions)

def f(n):
    """Calculates the largest odd divisor of n."""
    while n > 0 and n % 2 == 0:
        n //= 2
    return n

V = 5
max_u = 100
found_solutions = []

for u in range(1, max_u + 1):
    all_conditions_met = True

    # The conditions are: f(u+v+k) - f(u+k) must be a multiple of 4 for k=0 to v-1
    for k in range(V):
        n1 = u + V + k
        n2 = u + k

        diff = f(n1) - f(n2)

        if diff % 4 != 0:
            all_conditions_met = False
            break

    if all_conditions_met:
        found_solutions.append(u)

print(f"V={V}")
print(f"Number of solutions found up to u={max_u}: {len(found_solutions)}")
if found_solutions:
    print(f"First 10 solutions found: {found_solutions[:10]}")
else:
    print("No solutions found in the tested range.")

